prog='''import collections

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = collections.Counter(x for r in grid for x in r)
    bg = counts.most_common(1)[0][0]
    out0 = [r[:] for r in grid]

    # Case 1: full separator row of one non-background color:
    # tile the block above into the region below, filling background only.
    for si in range(h):
        row = grid[si]
        if len(set(row)) == 1 and row[0] != bg:
            block = grid[:si]
            out = [r[:] for r in out0]
            for i in range(si + 1, h):
                src = block[(i - si - 1) % len(block)]
                for j in range(w):
                    if out[i][j] == bg:
                        out[i][j] = src[j]
            return out

    def candidates(get, n):
        seen = {}
        cands = []
        for i in range(n):
            t = tuple(get(i))
            if any(x != bg for x in t):
                if t in seen:
                    cands.append((i - seen[t], seen[t]))
                else:
                    seen[t] = i
        return cands

    def best_block(p, n, has_content):
        best, best_s = -1, 0
        for s in range(p):
            cnt = sum(1 for k in range(s, min(s + p, n)) if has_content(k))
            if cnt > best:
                best, best_s = cnt, s
        return best_s

    def tile_v():
        cv = candidates(lambda i: grid[i], h)
        if not cv: return None
        p, _ = min(cv)
        s = best_block(p, h, lambda i: any(x != bg for x in grid[i]))
        out = [r[:] for r in out0]
        for i in range(h):
            src = s + ((i - s) % p)
            for j in range(w):
                if out[i][j] == bg:
                    out[i][j] = grid[src][j]
        return out

    def tile_h():
        ch = candidates(lambda j: [grid[i][j] for i in range(h)], w)
        if not ch: return None
        p, _ = min(ch)
        s = best_block(p, w, lambda j: any(grid[i][j] != bg for i in range(h)))
        out = [r[:] for r in out0]
        for j in range(w):
            src = s + ((j - s) % p)
            for i in range(h):
                if out[i][j] == bg:
                    out[i][j] = grid[i][src]
        return out

    opts = [o for o in (tile_v(), tile_h()) if o is not None]
    if not opts: return out0
    def changed(o): return sum(1 for a, b in zip([c for r in o for c in r],
                                                 [c for r in out0 for c in r]) if a != b)
    return max(opts, key=changed)

